/*
 * `od` did not exist: every dump answered "command not found", so the byte-level
 * views the other probes lean on (`od -c`, `od -An -tx1`) were unavailable. It is
 * now a coreutils module evaluating every option it accepts: -A radix, -j/-N with
 * hex and size suffixes, -S strings, -t with a, c, d, o, u, x, f of every size
 * (including the 80-bit long double, decoded with BigInt and printed with the
 * shortest digits that round-trip, as glibc's ftoastr does), the z suffix, -w and
 * its rounding to the common unit, duplicate suppression with `*` and -v,
 * --endian, several formats on one line with the field padding of the widest
 * one, --traditional offsets and labels, and the diagnostics of each refusal.
 *
 * Every expected string was produced by the real GNU coreutils 9.4 of the dev
 * container on the same input, by running the identical line in bash with
 * LC_ALL=C.UTF-8; typographic quotes are normalised on both sides. NOT covered,
 * because the machines differ: the version banner, `--help`, the content of
 * /etc/hostname and the privilege of /root (the harness runs bash as root).
 *
 * Measured against the commit before the module existed (worktree): 281 cases, 281 fall (od answered "command not found" at the base).
 */
import { describe, it, expect } from 'vitest';
import { LinuxPC } from '@/network/devices/LinuxPC';

type Sh = { executeCommand(line: string): Promise<string> };

const SETUP = "mkdir -p sub/deep sub/empty; printf 'hi\\n' > a.txt; printf 'yo\\n' > sub/b.log; : > sub/deep/c.txt; printf 'x%.0s' $(seq 1 3000) > big; ln -sf a.txt lnk; ln -sfn sub dlnk; ln -sfn nowhere dang; ln -sfn lnk2 lnk2; printf 'a.txt\\0sub\\0' > list0; chmod 600 sub/b.log; chmod 755 sub/deep; seq 1 10 > nums; printf 'foo bar\\nbaz qux\\nFoo BAR\\nhello world\\nbaz qux\\nbaz qux\\nz:y:x\\n' > words; printf 'a\\0b\\0a\\0' > z";

const normalise = (text: string): string => text.replace(/[‘’]/g, "'").replace(/\n+$/, '');

async function lab(): Promise<Sh> {
  const machine = new LinuxPC('linux-pc', 'PC1', 0, 0) as unknown as Sh & { powerOn(): void };
  machine.powerOn();
  await machine.executeCommand('mkdir -p /tmp/ff; cd /tmp/ff');
  return machine;
}

